
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
/* ---------- page layout: samples | preview | editor ---------- */
.w{display:grid;grid-template-columns:minmax(220px,270px) minmax(300px,420px) minmax(280px,1fr);grid-template-areas:"gal col ctl";gap:24px;align-items:start;padding:1rem 0}
.gal{grid-area:gal;min-width:0}.col{grid-area:col;min-width:0}.ctl{grid-area:ctl;min-width:0}
.w.rec{grid-template-columns:minmax(220px,360px) minmax(300px,440px);grid-template-areas:"gal col";justify-content:center}
@media (max-width:1150px){.w{grid-template-columns:minmax(300px,420px) minmax(280px,1fr);grid-template-areas:"col ctl" "gal gal"}}
@media (max-width:760px){.w,.w.rec{grid-template-columns:minmax(0,1fr);grid-template-areas:"col" "gal" "ctl"}}
.col{display:flex;flex-direction:column;align-items:center;gap:12px}
.btns{display:flex;gap:8px;flex-wrap:wrap;justify-content:center}
/* ---------- the stage (animated invitation) ---------- */
.st{--skin:#D9A47E;--hair:#22160F;--el:color-mix(in srgb,var(--ef) 90%,#000);--eb:color-mix(in srgb,var(--ef) 76%,#000);--fl:color-mix(in srgb,var(--ef) 95%,#000);--dr:color-mix(in srgb,var(--acc) 30%,var(--bg));--lt:color-mix(in srgb,var(--acc) 25%,#FFF8E6);--p2:color-mix(in srgb,var(--acc) 55%,#fff);--bl:#9E3B3B;--lv:#5E6B3A;--o:0s;--t0:5.8s;--te:13.3s;--bgo:.8;position:relative;width:100%;max-width:340px;aspect-ratio:9/16;overflow:hidden;border-radius:16px;cursor:pointer;container-type:inline-size;background:var(--bg);font-family:var(--ft),Georgia,serif}
.rec #st{max-width:420px}
.pd,.pc{display:none;position:absolute;inset:0;width:100%;height:100%;color:var(--acc)}
.pt-dia .pd,.pt-dot .pc{display:block}
.bgp{opacity:.16}.cdp{opacity:.07}
.bgimg{display:none;position:absolute;inset:0;background-size:cover;background-position:center;pointer-events:none}
.bgs .bgimg.stg,.bgc .bgimg.crd{display:block}
.bgimg.stg{opacity:var(--bgo)}
.bgimg.crd{opacity:calc(var(--bgo) * .45)}
.env-l,.door-l,.med-l{display:none}
.s-env .env-l,.s-door .door-l,.s-med .med-l{display:block}
.ia,.ic{font-style:italic;font-weight:500;font-size:15px;font-size:max(12px,4.6cqw)}
.ib{font-family:var(--fs),'Snell Roundhand',Georgia,serif;font-size:48px;font-size:14.5cqw;line-height:1.15}
.eintro{position:absolute;top:11%;left:6%;right:6%;text-align:center;z-index:4;opacity:0;color:var(--it)}
.envw{position:absolute;left:11%;width:78%;top:42%;aspect-ratio:3/2;z-index:3;opacity:0}
.env{position:relative;width:100%;height:100%;perspective:700px}
.env>div{position:absolute}
.eb{inset:0;background:var(--eb);border-radius:6px;z-index:1}
.mini{left:6%;right:6%;top:6%;bottom:6%;background:var(--cd);border-radius:4px;z-index:2;transform:translateY(-55%)}
.mini::after{content:"";position:absolute;inset:7%;border:1px solid var(--acc);border-radius:3px}
.efr{inset:0;background:var(--ef);clip-path:polygon(0 0,50% 52%,100% 0,100% 100%,0 100%);border-radius:6px;z-index:3}
.ebt{inset:0;background:var(--el);clip-path:polygon(0 100%,50% 56%,100% 100%);border-radius:6px;z-index:3}
.flap{left:0;top:0;width:100%;height:50%;background:var(--eb);clip-path:polygon(0 0,100% 0,50% 100%);transform-origin:50% 0;transform:rotateX(180deg);z-index:1}
.eseal{left:40%;top:35%;width:20%;aspect-ratio:1;border-radius:50%;background:var(--acc);color:var(--cd);display:flex;align-items:center;justify-content:center;font-size:15px;font-size:4.6cqw;font-weight:500;z-index:5;opacity:0}
.dz{position:absolute;inset:0;z-index:3;perspective:1100px;opacity:0}
.lf,.rf,.fr{position:absolute;inset:0;width:100%;height:100%;color:var(--acc)}
.lf{transform-origin:8.9% 50%;transform:rotateY(105deg)}
.rf{transform-origin:91.1% 50%;transform:rotateY(-105deg)}
.pl{position:absolute;left:14%;right:14%;top:26%;padding:5% 4%;background:var(--bg);border:1px solid var(--acc);border-radius:10px;text-align:center;color:var(--it);z-index:5;opacity:0}
.pl .ib,.mintro .ib{color:var(--acc)}
.sl{display:none;position:absolute;left:50%;top:60%;width:17cqw;height:17cqw;margin-left:-8.5cqw;border-radius:50%;background:var(--acc);color:var(--bg);align-items:center;justify-content:center;font-size:16px;font-size:5cqw;font-weight:500;z-index:5;opacity:0}
.s-door .sl{display:flex}
.med{position:absolute;left:17%;width:66%;top:15%;aspect-ratio:1;z-index:3;opacity:0}
.mr{position:absolute;inset:0;width:100%;height:100%;color:var(--acc)}
.r1,.r3{fill:none;stroke:currentColor;stroke-dasharray:1;stroke-dashoffset:0}.r1{stroke-width:.9}.r3{stroke-width:.45}
.r2{fill:none;stroke:currentColor;stroke-width:1.1;stroke-dasharray:.6 2.6;transform-box:fill-box;transform-origin:center;animation:spin 24s linear infinite}
.mono{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;gap:2cqw;font-family:var(--fs),'Snell Roundhand',Georgia,serif;color:var(--it);font-size:64px;font-size:19cqw;line-height:1}
.mono span,.mono i{display:inline-block}
.mono i{font-style:italic;font-family:var(--ft),Georgia,serif;font-size:26px;font-size:8cqw;color:var(--acc)}
.mintro{position:absolute;left:8%;right:8%;top:67%;text-align:center;color:var(--it);z-index:3;opacity:0}
.card{position:absolute;inset:0;background:var(--cd);z-index:6;overflow:hidden}
.s-door .card{z-index:1}
.b-arch,.b-l1,.b-l2,.b-cn,.b-g{display:none}
.b-arch{position:absolute;inset:0;width:100%;height:100%;color:var(--acc)}
.a1,.a2{fill:none;stroke:currentColor;stroke-dasharray:1;stroke-dashoffset:0}
.tip{transform-box:fill-box;transform-origin:center}
.b-l1{position:absolute;inset:3.5%;border:1px solid var(--acc);border-radius:8px}
.b-l2{position:absolute;inset:5%;border:1px solid var(--acc);border-radius:6px;opacity:.5}
.b-cn{position:absolute;width:17cqw;height:17cqw;color:var(--acc)}
.b-cn.tl{left:5%;top:3%}.b-cn.tr{right:5%;top:3%;transform:scaleX(-1)}.b-cn.bl{left:5%;bottom:3%;transform:scaleY(-1)}.b-cn.br{right:5%;bottom:3%;transform:scale(-1,-1)}
.cg{width:100%;height:100%;transform-origin:0 0}
.b-g{position:absolute;left:10%;width:80%;height:auto;color:var(--acc)}
.b-g.gt{top:3%}.b-g.gb{bottom:3%;transform:scaleY(-1)}
.g1,.g2{fill:none;stroke:currentColor;stroke-dasharray:1;stroke-dashoffset:0}.g1{stroke-width:.7}.g2{stroke-width:.4}
.bdc circle{fill:currentColor}
.bd-arch .b-arch,.bd-double .b-l1,.bd-double .b-l2,.bd-single .b-l1,.bd-corner .b-l1,.bd-corner .b-l2,.bd-corner .b-cn,.bd-garland .b-l1,.bd-garland .b-g{display:block}
.sp{display:none;position:absolute;width:16px;width:5cqw;height:auto;color:var(--acc);opacity:0}
.spk .sp{display:block}
.in{position:absolute;left:13%;right:13%;top:14%;bottom:7%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:3px;color:var(--ink)}
.bd-arch .in{top:16%;bottom:6%}
.bd-garland .in{top:13%;bottom:13%}
.bism{font-family:Amiri,'Noto Naskh Arabic',serif;font-size:21px;font-size:max(14px,6cqw);line-height:1.5;color:var(--ink2)}
.orn{width:40%;height:auto;color:var(--acc);margin:3px 0}
.sm{font-weight:500;font-size:13px;font-size:max(11px,4cqw);letter-spacing:.05em}
.it{font-style:italic;letter-spacing:0}
.nm{font-family:var(--fs),'Noto Nastaliq Urdu','Snell Roundhand',Georgia,serif;font-size:46px;font-size:13.5cqw;line-height:1.1;width:100%}
.nm .w2,.nm .l{display:inline-block}.nm .w2{white-space:nowrap}
.ns{width:100%;height:auto;overflow:visible;display:block}
.nt{font-family:var(--fs),'Snell Roundhand',Georgia,serif;font-size:58px;fill:var(--ink);stroke:var(--ink);stroke-width:.9;stroke-dasharray:320;stroke-dashoffset:0}
.amp{font-style:italic;font-weight:500;font-size:26px;font-size:7.5cqw;line-height:1;color:var(--ink2)}
.ev{font-size:31px;font-size:9cqw;font-weight:500;letter-spacing:.16em;color:var(--ink2);margin:2px 0}
.dt{font-size:17px;font-size:max(12px,5cqw);font-weight:500}
.tm,.vn{font-weight:500;font-size:14px;font-size:max(11px,4.3cqw)}
.vn,.cl{font-style:italic}
.cl{font-family:var(--ft),'Noto Nastaliq Urdu',Georgia,serif;font-weight:500;font-size:13px;font-size:max(11px,4cqw);color:var(--ink2)}
.ln{display:none;position:absolute;top:0;width:9cqw;height:auto;color:var(--acc);transform-origin:50% 0;z-index:7;animation:sw 2.6s ease-in-out infinite alternate}
.lan .ln{display:block}
.ln.a{left:22%}.ln.b{right:22%;animation-delay:-1.3s}
.fall{position:absolute;inset:0;z-index:7;pointer-events:none;overflow:hidden}
.pe{position:absolute;top:-6%;background:var(--acc);border-radius:60% 0 60% 0}
.pe.alt{background:var(--p2)}
.du{position:absolute;top:104%;border-radius:50%;background:var(--acc);opacity:0}
.fd,.fo{position:absolute;inset:0;background:#000;z-index:9;opacity:0;pointer-events:none}
/* module wrappers: plain positioned boxes (no z-index, so their children join the stage / card stacking order) */
.ix,.bdx,.ptx,.orx{display:none;position:absolute;inset:0;pointer-events:none}
.sc{display:none;position:absolute;inset:0;pointer-events:none;z-index:8;opacity:0}
/* ---------- editor ---------- */
.ctl{display:flex;flex-direction:column;gap:12px}
.ctl label{display:flex;flex-direction:column;gap:4px;font-size:13px;color:var(--text-secondary)}
.ctl label.ck{flex-direction:row;align-items:center;gap:8px}
.ctl input[type=text],.ctl select{width:100%}
.grp{font-size:14px;font-weight:500;color:var(--text-primary);margin-top:6px;padding-top:10px;border-top:0.5px solid var(--border)}
.g2c{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:10px}
.ckg{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px 12px}
.g2c input[type=color]{width:100%;height:36px;padding:2px;border:0.5px solid var(--border);border-radius:var(--radius);background:transparent;cursor:pointer}
.hint{font-size:12px;color:var(--text-secondary);line-height:1.4}
.hid{display:none}
/* ---------- samples gallery ---------- */
.gal{display:flex;flex-direction:column;gap:10px}
.galh{display:flex;align-items:baseline;justify-content:space-between;gap:8px}
.galh b{font-size:14px;font-weight:500;color:var(--text-primary)}
.galh span{font-size:12px;color:var(--text-secondary)}
.chips{display:flex;flex-wrap:wrap;gap:6px}
#w .chips button.chip{padding:4px 10px;font-size:12px;line-height:1.3;border-radius:999px;border:0.5px solid var(--border-strong);background:transparent;color:var(--text-secondary);transform:none}
#w .chips button.chip:hover{background:var(--surface-1);color:var(--text-primary)}
#w .chips button.chip.on{background:var(--text-primary);color:var(--surface-1);border-color:var(--text-primary)}
.ggrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(98px,1fr));gap:12px 10px;max-height:calc(100vh - 150px);overflow-y:auto;padding:3px 6px 10px 3px;scrollbar-width:thin}
@media (max-width:1150px){.ggrid{max-height:none;overflow:visible;grid-template-columns:repeat(auto-fill,minmax(104px,1fr))}}
#w .gal button.th{display:flex;flex-direction:column;gap:6px;padding:0;margin:0;border:0;background:none;border-radius:12px;color:var(--text-primary);text-align:left;cursor:pointer;transform:none;min-width:0}
#w .gal button.th:hover{background:none}
#w .gal button.th:active{background:none;transform:scale(.98)}
.tbox{position:relative;width:100%;aspect-ratio:9/16;border-radius:10px;overflow:hidden;box-shadow:0 0 0 .5px var(--border-strong),0 3px 10px rgb(0 0 0 / .14);transition:box-shadow .15s ease,transform .15s ease}
.th:hover .tbox{transform:translateY(-2px);box-shadow:0 0 0 1px var(--border-stronger),0 6px 16px rgb(0 0 0 / .18)}
.th.on .tbox{box-shadow:0 0 0 2.5px #C9A24E,0 6px 18px rgb(0 0 0 / .22)}
.tbox>.tstage{position:absolute;left:0;top:0;width:340px!important;max-width:none!important;border-radius:0;transform-origin:0 0;transform:scale(var(--ts,.3));cursor:inherit;pointer-events:none}
.tstage *,.tstage{animation:none!important;transition:none!important}
.tnum{position:absolute;left:6px;top:6px;z-index:20;min-width:20px;text-align:center;background:rgb(0 0 0 / .58);color:#fff;font:600 11px/1 var(--font-sans);padding:4px 6px;border-radius:7px;letter-spacing:.02em}
.th.on .tnum{background:#C9A24E;color:#1d140c}
.tck{display:none;position:absolute;right:6px;top:6px;z-index:20;width:20px;height:20px;border-radius:50%;background:#C9A24E;color:#1d140c;align-items:center;justify-content:center;font-size:13px;font-weight:700}
.th.on .tck{display:flex}
.tn{display:flex;flex-direction:column;gap:1px;font-size:12px;line-height:1.25;padding:0 2px}
.tn b{font-weight:500;color:var(--text-primary)}
.tn span{color:var(--text-secondary);font-size:11px}
.th[hidden]{display:none!important}
/* sample navigation above the preview */
.snav{display:flex;align-items:center;gap:10px;width:100%;max-width:420px}
#w .snav button.nv{width:36px;height:36px;padding:0;flex:none;border-radius:50%;font-size:20px;line-height:1;display:flex;align-items:center;justify-content:center;transform:none}
.snt{flex:1;min-width:0;text-align:center;display:flex;flex-direction:column;gap:1px}
.snt b{font-size:14px;font-weight:500;color:var(--text-primary)}
.snt span{font-size:12px;color:var(--text-secondary);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* client view */
.chead,.evsw,#bLike{display:none}
.client .chead{display:flex;flex-direction:column;align-items:center;gap:2px;text-align:center}
.client .evsw{display:flex;gap:6px;justify-content:center}
.client #bLike{display:inline-flex}
.client #bHide,.client #bExport,.client .ctl{display:none!important}
.chead b{font-size:18px;font-weight:500;color:var(--text-primary)}
.chead span{font-size:13px;color:var(--text-secondary)}
#w .evsw button.evb{padding:5px 14px;border-radius:999px;font-size:13px;transform:none}
#w .evsw button.evb.on{background:var(--text-primary);color:var(--surface-1);border-color:var(--text-primary)}
#w button#bLike{background:#C9A24E;color:#1d140c;border-color:#C9A24E;font-weight:500}
#w button#bLike:hover{background:#d6b162}
@media (hover:none){#kbdHint{display:none}}
#bVideo{display:none!important}   /* in-browser video download is switched off for now */
/* "Download video": the card fills the window height while the browser records it */
html.recording,html.recording body{overflow:hidden!important;background:#000!important;cursor:none!important}
html.recording #st{position:fixed!important;left:50%!important;top:0!important;height:100vh!important;width:calc(100vh * 9 / 16)!important;max-width:none!important;margin-left:calc(100vh * -9 / 32)!important;border-radius:0!important;z-index:2147483647!important;cursor:none!important}
html.recording .recmsg{display:block}
.recmsg{display:none;position:fixed;left:12px;top:12px;z-index:2147483647;color:#fff;font:13px/1.4 var(--font-sans);background:rgb(0 0 0 / .6);padding:6px 10px;border-radius:8px}
.toast{position:fixed;left:50%;bottom:24px;transform:translateX(-50%) translateY(20px);background:var(--text-primary);color:var(--surface-1);padding:10px 16px;border-radius:10px;font-size:14px;opacity:0;pointer-events:none;transition:opacity .2s,transform .2s;z-index:100;max-width:calc(100vw - 32px);text-align:center}
.toast.on{opacity:1;transform:translateX(-50%) translateY(0)}
dialog.dlg{border:0.5px solid var(--border-strong);border-radius:14px;padding:0;background:var(--surface-2);color:var(--text-primary);max-width:min(440px,calc(100vw - 32px));box-shadow:0 12px 40px rgb(0 0 0 / .25)}
dialog.dlg::backdrop{background:rgb(0 0 0 / .4)}
.dlgf{display:flex;flex-direction:column;gap:12px;padding:18px}
.dlgf>b{font-size:16px;font-weight:500}
.dlgf p{font-size:13px;line-height:1.5;color:var(--text-secondary)}
.dlgf label{display:flex;flex-direction:column;gap:4px;font-size:13px;color:var(--text-secondary)}
.dlgf label.ck{flex-direction:row;align-items:center;gap:8px}
.dlgb{display:flex;justify-content:flex-end;gap:8px;margin-top:4px}
/* ---------- keyframes ---------- */
@keyframes sw{0%{transform:rotate(-6deg)}100%{transform:rotate(6deg)}}
@keyframes spin{0%{transform:rotate(0deg)}100%{transform:rotate(360deg)}}
@keyframes fdK{0%{opacity:1}100%{opacity:0}}
@keyframes foK{0%{opacity:0}100%{opacity:1}}
@keyframes fade{0%{opacity:0}100%{opacity:1}}
@keyframes up{0%{opacity:0;transform:translateY(10px)}100%{opacity:1;transform:none}}
@keyframes eIntro{0%,88%{opacity:1}100%{opacity:0}}
@keyframes envK{0%{opacity:0;transform:translateY(30px)}18%,84%{opacity:1;transform:none}100%{opacity:0;transform:translateY(40px)}}
@keyframes sealK{0%{opacity:1;transform:scale(1)}40%{opacity:1;transform:scale(1.12)}100%{opacity:0;transform:scale(.5)}}
@keyframes flapK{0%{transform:rotateX(0deg);z-index:4;background:var(--fl)}50%{z-index:4;background:var(--fl)}51%{z-index:1;background:var(--eb)}100%{transform:rotateX(180deg);z-index:1;background:var(--eb)}}
@keyframes miniK{0%{transform:none}100%{transform:translateY(-55%)}}
@keyframes zoomK{0%{opacity:0;transform:translateY(-7.6%) scale(.62)}20%{opacity:1}100%{opacity:1;transform:none}}
@keyframes circK{0%{clip-path:circle(0% at 50% 40%)}100%{clip-path:circle(120% at 50% 40%)}}
@keyframes dzK{0%,86%{opacity:1}100%{opacity:0}}
@keyframes lfK{0%{transform:rotateY(0deg)}100%{transform:rotateY(105deg)}}
@keyframes rfK{0%{transform:rotateY(0deg)}100%{transform:rotateY(-105deg)}}
@keyframes plK{0%{opacity:0;transform:scale(.92)}12%{opacity:1;transform:none}88%{opacity:1;transform:none}100%{opacity:0;transform:scale(.96)}}
@keyframes slK{0%{opacity:0;transform:scale(0)}10%{opacity:1;transform:scale(1.15)}16%{opacity:1;transform:scale(1)}85%{opacity:1;transform:scale(1)}100%{opacity:0;transform:scale(.6)}}
@keyframes medK{0%,82.6%{opacity:1;transform:none}100%{opacity:0;transform:scale(1.5)}}
@keyframes minK{0%,82.6%{opacity:1;transform:none}100%{opacity:0;transform:translateY(20px)}}
@keyframes monoK{0%{opacity:0;transform:scale(.4) translateY(10%)}100%{opacity:1;transform:none}}
@keyframes drawK{0%{stroke-dashoffset:1}100%{stroke-dashoffset:0}}
@keyframes popK{0%{opacity:0;transform:scale(0)}70%{opacity:1;transform:scale(1.2)}100%{opacity:1;transform:scale(1)}}
@keyframes cnK{0%{opacity:0;transform:scale(0)}100%{opacity:1;transform:none}}
@keyframes letterK{0%{opacity:0;transform:translateY(45%) rotate(-10deg)}100%{opacity:1;transform:none}}
@keyframes slL{0%{opacity:0;transform:translateX(-35%);letter-spacing:.25em}100%{opacity:1;transform:none;letter-spacing:0}}
@keyframes slR{0%{opacity:0;transform:translateX(35%);letter-spacing:.25em}100%{opacity:1;transform:none;letter-spacing:0}}
@keyframes fadeS{0%{opacity:0;transform:scale(1.08)}100%{opacity:1;transform:none}}
@keyframes revK{0%{clip-path:inset(-20% 100% -20% -20%)}100%{clip-path:inset(-20% -20% -20% -20%)}}
@keyframes wrK{0%{stroke-dashoffset:320;fill-opacity:0}65%{stroke-dashoffset:0;fill-opacity:0}100%{stroke-dashoffset:0;fill-opacity:1}}
@keyframes ampK{0%{opacity:0;transform:rotate(-180deg) scale(.3)}100%{opacity:1;transform:none}}
@keyframes lnK{0%{opacity:0;transform:scaleX(0)}100%{opacity:1;transform:scaleX(1)}}
@keyframes trK{0%{opacity:0;letter-spacing:.7em}100%{opacity:1;letter-spacing:.16em}}
@keyframes wipeK{0%{opacity:0;clip-path:inset(0 50% 0 50%)}100%{opacity:1;clip-path:inset(0 0 0 0)}}
@keyframes sdL{0%{opacity:0;transform:translateX(-30%)}100%{opacity:1;transform:none}}
@keyframes sdR{0%{opacity:0;transform:translateX(30%)}100%{opacity:1;transform:none}}
@keyframes twK{0%,100%{opacity:0;transform:scale(0) rotate(0deg)}50%{opacity:1;transform:scale(1) rotate(45deg)}}
@keyframes fallK{0%{top:-6%;transform:translateX(0) rotate(0deg)}50%{transform:translateX(14px) rotate(160deg)}100%{top:104%;transform:translateX(-8px) rotate(320deg)}}
@keyframes duK{0%{top:104%;opacity:0}15%{opacity:.9}85%{opacity:.9}100%{top:-4%;opacity:0}}
/* ---------- timeline: --o = length of the story scenes before the opening; --t0 = card time ---------- */
.play.fdi .fd{animation:fdK 1s ease-out both}
