/* ---- motion ---- */
.play.s-love-map .lm-all{animation:love-map-all 9s ease-in var(--o) both}
.play.s-love-map .lm-paper{animation:love-map-cam 9s cubic-bezier(.3,.1,.3,1) var(--o) both}
.play.s-love-map .lm-gl{animation:love-map-fade 1.2s ease-out calc(var(--o) + .2s) both}
.play.s-love-map .lm-head>*{animation:love-map-up 1.2s cubic-bezier(.2,.8,.2,1) calc(var(--o) + .25s) both}
.play.s-love-map .lm-ev{animation-delay:calc(var(--o) + .5s)}
.play.s-love-map .lm-rule{animation-name:love-map-rule;animation-delay:calc(var(--o) + .8s)}
