/* ---- intros:typewriter ---- */
.ix-typewriter .tw-all{position:absolute;inset:0;z-index:5;opacity:0;overflow:hidden;
  --tb:color-mix(in srgb,var(--ink) 88%,var(--bg));--tb2:color-mix(in srgb,var(--tb) 85%,#fff);--tb3:color-mix(in srgb,var(--tb) 62%,#000);
  --tk:color-mix(in srgb,var(--tb) 42%,#000);--pk:color-mix(in srgb,var(--ef) 13%,#000);--mono:'Courier Prime','Courier New',Courier,monospace}
.ix-typewriter .tw-bg{position:absolute;inset:0;background:radial-gradient(120% 70% at 50% 40%,color-mix(in srgb,var(--bg) 88%,var(--acc)) 0%,var(--bg) 60%,color-mix(in srgb,var(--bg) 86%,#000) 100%)}
.ix-typewriter .tw-kick{position:absolute;left:0;right:0;top:8cqw;text-align:center;font-family:var(--ft),Georgia,serif;font-size:3.3cqw;letter-spacing:.42em;text-transform:uppercase;color:color-mix(in srgb,var(--it) 80%,transparent)}
.ix-typewriter .tw-kick span{margin-right:-.42em}
.ix-typewriter .tw-kick b{display:block;width:12cqw;height:1px;margin:2.6cqw auto 0;background:color-mix(in srgb,var(--acc) 70%,transparent)}

/* carriage: nested wrappers, one pair per typed line (a = move to line start, b = typing + return) */
.ix-typewriter .tw-car,.ix-typewriter .tw-a,.ix-typewriter .tw-b,.ix-typewriter .tw-v,.ix-typewriter .tw-feed{position:absolute;inset:0}
.ix-typewriter .tw-a,.ix-typewriter .tw-b{font-family:var(--mono);font-size:3.5cqw}
.ix-typewriter .tw-a.a3,.ix-typewriter .tw-b.b3{font-size:4.8cqw;font-weight:700}
.ix-typewriter .tw-a.a1{transform:translateX(calc(var(--n,22) * .5ch))}
.ix-typewriter .tw-feed{clip-path:inset(-200cqw -200cqw 73.78cqw -200cqw)}
.ix-typewriter .tw-v.v2{--dv:2}.ix-typewriter .tw-v.v3{--dv:1.5}.ix-typewriter .tw-v.v4{--dv:1.5}.ix-typewriter .tw-v.v5{--dv:1.5}.ix-typewriter .tw-v.v6{--dv:2}
.ix-typewriter .tw-paper{position:absolute;left:17cqw;width:66cqw;top:72cqw;height:117cqw;border-radius:.4cqw;
  background:linear-gradient(180deg,color-mix(in srgb,var(--ef) 96%,#fff) 0,var(--ef) 40%,color-mix(in srgb,var(--ef) 97%,#000) 100%);
  box-shadow:0 .5cqw 2.4cqw rgb(0 0 0 / .22),inset 0 0 0 1px color-mix(in srgb,var(--pk) 7%,transparent)}
.ix-typewriter .tw-paper::after{content:"";position:absolute;inset:3cqw;border:1px solid color-mix(in srgb,var(--acc) 42%,transparent);border-radius:.3cqw;pointer-events:none}
.ix-typewriter .tw-ph{position:absolute;left:0;right:0;top:7cqw;display:flex;align-items:center;justify-content:center;gap:3cqw;color:var(--acc)}
.ix-typewriter .tw-ph b{display:block;width:8cqw;height:1px;background:color-mix(in srgb,var(--acc) 65%,transparent)}
.ix-typewriter .tw-mono{font-family:var(--fs),Georgia,serif;font-size:6.6cqw;line-height:1;display:flex;align-items:baseline;gap:.8cqw}
.ix-typewriter .tw-mono i{font-style:normal;font-family:var(--ft),Georgia,serif;font-size:3.4cqw;opacity:.8}
.ix-typewriter .tw-tx{position:absolute;inset:0}
.ix-typewriter .tw-l{position:absolute;left:calc(50% - var(--n,22) * .5ch);width:calc(var(--n,22) * 1ch);height:6cqw;line-height:6cqw;
  white-space:pre;overflow:hidden;font-family:var(--mono);font-size:3.5cqw;color:var(--pk);text-shadow:0 0 .12cqw color-mix(in srgb,var(--pk) 45%,transparent)}
.ix-typewriter .tw-l.l1{top:21cqw}.ix-typewriter .tw-l.l2{top:33cqw}.ix-typewriter .tw-l.l3{top:42cqw}
.ix-typewriter .tw-l.l4{top:51cqw}.ix-typewriter .tw-l.l5{top:60cqw}.ix-typewriter .tw-l.l6{top:72cqw}
.ix-typewriter .tw-l.l3{font-size:4.8cqw;font-weight:700;text-transform:uppercase;color:color-mix(in srgb,var(--ink2) 70%,var(--pk))}
.ix-typewriter .tw-l.l3 span{text-transform:uppercase}

/* platen (moves with the carriage) */
.ix-typewriter .tw-plat,.ix-typewriter .tw-body,.ix-typewriter .tw-guide svg{position:absolute;left:0;top:0;width:100%;height:100%;overflow:visible}
.ix-typewriter .tw-cf{fill:var(--tb3)}
.ix-typewriter .tw-plh{stroke:rgb(255 255 255 / .2);stroke-width:.35}
