.ix-typewriter .tw-kn{fill:var(--tb);stroke:var(--acc);stroke-width:.3}
.ix-typewriter .tw-rid{stroke:color-mix(in srgb,var(--acc) 55%,transparent);stroke-width:7.2;stroke-dasharray:.18 .62}
.ix-typewriter .tw-lev{fill:none;stroke:var(--tb2);stroke-width:1.1;stroke-linecap:round}
.ix-typewriter .tw-lev2{fill:none;stroke:var(--acc);stroke-width:1.7;stroke-linecap:round}

/* body (fixed) */
.ix-typewriter .tw-rail{fill:var(--tb3)}
.ix-typewriter .tw-hl{stroke:color-mix(in srgb,var(--acc) 85%,transparent);stroke-width:.3}
.ix-typewriter .tw-hl2{stroke:color-mix(in srgb,var(--acc) 45%,transparent);stroke-width:.25}
.ix-typewriter .tw-deck{fill:var(--tb2);stroke:color-mix(in srgb,var(--acc) 60%,transparent);stroke-width:.3}
.ix-typewriter .tw-bask{fill:var(--tk);stroke:var(--acc);stroke-width:.3}
.ix-typewriter .tw-fan line{stroke:color-mix(in srgb,var(--acc) 75%,transparent);stroke-width:.32;stroke-linecap:round}
.ix-typewriter .tw-sp{fill:var(--tb);stroke:var(--acc);stroke-width:.3}
.ix-typewriter .tw-sp2{fill:var(--tk);stroke:color-mix(in srgb,var(--acc) 55%,transparent);stroke-width:.25}
.ix-typewriter .tw-sp3{fill:var(--acc)}
.ix-typewriter .tw-front{fill:var(--tb);stroke:color-mix(in srgb,var(--acc) 40%,transparent);stroke-width:.25}
.ix-typewriter .tw-badge{fill:none;stroke:var(--acc);stroke-width:.25}
.ix-typewriter .tw-bt{font-family:var(--mono);font-size:2.3px;letter-spacing:.3px;fill:var(--acc)}
.ix-typewriter .tw-ks{fill:rgb(0 0 0 / .35)}
.ix-typewriter .tw-kc{fill:var(--tk);stroke:var(--acc);stroke-width:.32}
.ix-typewriter .tw-kr{fill:none;stroke:color-mix(in srgb,var(--ef) 30%,transparent);stroke-width:.15}
.ix-typewriter .tw-kt{font-family:var(--mono);font-size:2.1px;font-weight:700;fill:color-mix(in srgb,var(--ef) 88%,transparent)}
.ix-typewriter .tw-spc{fill:var(--tk);stroke:var(--acc);stroke-width:.3}

/* type guide + ribbon at the printing point */
.ix-typewriter .tw-guide{position:absolute;inset:0}
.ix-typewriter .tw-gp{fill:var(--tb3);stroke:var(--acc);stroke-width:.25}
.ix-typewriter .tw-rib{position:absolute;left:47.4cqw;top:99.9cqw;width:2.4cqw;height:1.5cqw;border-radius:.2cqw;
  background:linear-gradient(180deg,var(--pk) 0 50%,color-mix(in srgb,var(--bl) 80%,#000) 50% 100%)}

/* bell */
.ix-typewriter .tw-dings{position:absolute;inset:0}
.ix-typewriter .tw-dg{position:absolute;left:79cqw;top:86cqw;display:flex;align-items:center;gap:1cqw;opacity:0;color:var(--acc)}
.ix-typewriter .tw-dg svg{width:4.2cqw;height:4.2cqw}
