.ix-typewriter .tw-dg span{font-family:var(--ft),Georgia,serif;font-style:italic;font-size:3.4cqw;letter-spacing:.06em;color:color-mix(in srgb,var(--acc) 70%,var(--it))}

/* ---------- motion ---------- */
.play.s-typewriter .tw-all{animation:typewriter-all 10.4s linear var(--o) both}
.play.s-typewriter .tw-kick{animation:typewriter-out .6s ease-in calc(var(--o) + 7.5s) both}
.play.s-typewriter .tw-a.a2,.play.s-typewriter .tw-a.a3,.play.s-typewriter .tw-a.a4,.play.s-typewriter .tw-a.a5,.play.s-typewriter .tw-a.a6{
  animation:typewriter-ret .38s cubic-bezier(.55,0,.15,1) calc(var(--o) + var(--r)) both}
.play.s-typewriter .tw-b{animation:typewriter-type calc(var(--n) * var(--dt)) steps(var(--n),end) calc(var(--o) + var(--s)) both,
  typewriter-ret .38s cubic-bezier(.55,0,.15,1) calc(var(--o) + var(--e) + .03s) both}
.play.s-typewriter .tw-v{animation:typewriter-adv .32s cubic-bezier(.3,.7,.2,1) calc(var(--o) + var(--r) + .06s) both}
.play.s-typewriter .tw-l{animation:typewriter-w calc(var(--n) * var(--dt)) steps(var(--n),end) calc(var(--o) + var(--s)) both}
.play.s-typewriter .tw-h{animation:typewriter-hit var(--dt) ease-out calc(var(--o) + var(--s)) var(--n) both}
.play.s-typewriter .tw-dg{animation:typewriter-ding 1s cubic-bezier(.2,.8,.2,1) calc(var(--o) + var(--t)) both}
.play.s-typewriter .tw-k{animation:typewriter-key var(--kp) ease-out calc(var(--o) + var(--kd)) var(--kc) both}
.play.s-typewriter .tw-feed{animation:typewriter-open .01s steps(1,end) calc(var(--o) + 8.62s) both}
.play.s-typewriter .tw-paper{animation:typewriter-pull 1.7s linear calc(var(--o) + 8s) both}
.play.s-typewriter .tw-tx,.play.s-typewriter .tw-ph{animation:typewriter-out .4s ease-in calc(var(--o) + 8.95s) both}
.play.s-typewriter .tw-plat,.play.s-typewriter .tw-body,.play.s-typewriter .tw-guide,.play.s-typewriter .tw-dings{animation:typewriter-away .8s cubic-bezier(.5,0,.7,1) calc(var(--o) + 8.05s) both}
.play.s-typewriter .card{animation:typewriter-card .85s ease-out calc(var(--o) + 9.15s) both}

@keyframes typewriter-all{0%,96%{opacity:1}100%{opacity:0}}
