/* Rose petals - fall (p), lateral drift with a lean (q), flutter: full flip or rocking (r) */
.fx-rose-petals .rose-petals-defs{position:absolute;width:0;height:0;overflow:hidden}
.fx-rose-petals .rose-petals-p{position:absolute;top:0;display:block;width:var(--s);height:calc(var(--s) * 1.1);margin-left:calc(var(--s) * -.5);opacity:0}
