@keyframes rose-petals-fall{
  0%{transform:translate3d(0,-12cqw,0);opacity:0}
  4%{opacity:var(--a)}
  95%{opacity:var(--a)}
  100%{transform:translate3d(0,190cqw,0);opacity:0}
}
